def solve(nums):
    def can_reach(index, reached):
        if index >= len(nums):
            return False
        if index == len(nums) - 1:
            return True
        if index in reached:
            return False
        reached.add(index)
        for i in range(index + 1, min(index + nums[index] + 1, len(nums))):
            if can_reach(i, reached):
                return True
        return False

    return can_reach(0, set())
```

